import{_ as s,c as a,e as p,o as e}from"./app-WxxISwYx.js";const t={};function o(l,n){return e(),a("div",null,n[0]||(n[0]=[p(`<h1 id="scikit-learn-치트시트" tabindex="-1"><a class="header-anchor" href="#scikit-learn-치트시트"><span>scikit-learn 치트시트</span></a></h1><p>지도 학습 실무에서 손에 익혀두면 시간을 아끼는 코드 패턴을 모았다. 개념 배경은 <a href="/study/supervised-learning/04-cross-validation-tuning">교차 검증과 튜닝</a>, <a href="/study/supervised-learning/16-feature-engineering-pipeline">피처 엔지니어링과 파이프라인</a>, <a href="/study/supervised-learning/15-gbdt-tuning">GBDT 실전 튜닝</a>에서 더 깊이 다룬다. 버전에 따라 인자 이름이 바뀔 수 있으니 최종 확인은 공식 문서로 한다.</p><h2 id="데이터-분할-—-train-test-split" tabindex="-1"><a class="header-anchor" href="#데이터-분할-—-train-test-split"><span>데이터 분할 — train_test_split</span></a></h2><p>가장 기본이 되는 홀드아웃 분할이다. 분류에서는 클래스 비율을 유지하도록 <code>stratify</code>를 반드시 넘긴다.</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>model_selection <span class="token keyword">import</span> train_test_split</span>
<span class="line"></span>
<span class="line">X_train<span class="token punctuation">,</span> X_test<span class="token punctuation">,</span> y_train<span class="token punctuation">,</span> y_test <span class="token operator">=</span> train_test_split<span class="token punctuation">(</span></span>
<span class="line">    X<span class="token punctuation">,</span> y<span class="token punctuation">,</span></span>
<span class="line">    test_size<span class="token operator">=</span><span class="token number">0.2</span><span class="token punctuation">,</span></span>
<span class="line">    random_state<span class="token operator">=</span><span class="token number">42</span><span class="token punctuation">,</span></span>
<span class="line">    stratify<span class="token operator">=</span>y<span class="token punctuation">,</span>          <span class="token comment"># 분류: 클래스 비율 유지</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="교차-검증-—-cross-val-score-cross-validate" tabindex="-1"><a class="header-anchor" href="#교차-검증-—-cross-val-score-cross-validate"><span>교차 검증 — cross_val_score / cross_validate</span></a></h2><p><code>cross_val_score</code>는 단일 지표를, <code>cross_validate</code>는 여러 지표와 학습 시간을 함께 돌려준다. <code>scoring</code>은 큰 값이 좋은 쪽으로 통일된다(오차 지표는 <code>neg_</code> 접두사).</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>model_selection <span class="token keyword">import</span> cross_val_score<span class="token punctuation">,</span> cross_validate</span>
<span class="line"></span>
<span class="line">scores <span class="token operator">=</span> cross_val_score<span class="token punctuation">(</span>model<span class="token punctuation">,</span> X<span class="token punctuation">,</span> y<span class="token punctuation">,</span> cv<span class="token operator">=</span><span class="token number">5</span><span class="token punctuation">,</span> scoring<span class="token operator">=</span><span class="token string">&quot;f1_macro&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>scores<span class="token punctuation">.</span>mean<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> scores<span class="token punctuation">.</span>std<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">results <span class="token operator">=</span> cross_validate<span class="token punctuation">(</span></span>
<span class="line">    model<span class="token punctuation">,</span> X<span class="token punctuation">,</span> y<span class="token punctuation">,</span> cv<span class="token operator">=</span><span class="token number">5</span><span class="token punctuation">,</span></span>
<span class="line">    scoring<span class="token operator">=</span><span class="token punctuation">[</span><span class="token string">&quot;accuracy&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;roc_auc&quot;</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    return_train_score<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">,</span>     <span class="token comment"># train/valid 격차로 과적합 진단</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="교차-검증-분할기-—-stratified-group-timeseries" tabindex="-1"><a class="header-anchor" href="#교차-검증-분할기-—-stratified-group-timeseries"><span>교차 검증 분할기 — Stratified / Group / TimeSeries</span></a></h2><p>문제 성격에 맞는 분할기를 <code>cv</code>에 직접 넘긴다. 잘못 고르면 leakage로 성능이 부풀려진다.</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>model_selection <span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    StratifiedKFold<span class="token punctuation">,</span> GroupKFold<span class="token punctuation">,</span> TimeSeriesSplit<span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 불균형 분류: fold마다 클래스 비율 유지</span></span>
<span class="line">skf <span class="token operator">=</span> StratifiedKFold<span class="token punctuation">(</span>n_splits<span class="token operator">=</span><span class="token number">5</span><span class="token punctuation">,</span> shuffle<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">,</span> random_state<span class="token operator">=</span><span class="token number">42</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 그룹 누수 방지: 같은 사용자/기기는 한 fold에만</span></span>
<span class="line">gkf <span class="token operator">=</span> GroupKFold<span class="token punctuation">(</span>n_splits<span class="token operator">=</span><span class="token number">5</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">for</span> tr<span class="token punctuation">,</span> va <span class="token keyword">in</span> gkf<span class="token punctuation">.</span>split<span class="token punctuation">(</span>X<span class="token punctuation">,</span> y<span class="token punctuation">,</span> groups<span class="token operator">=</span>groups<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 시계열: 과거로 학습, 미래로 검증</span></span>
<span class="line">tss <span class="token operator">=</span> TimeSeriesSplit<span class="token punctuation">(</span>n_splits<span class="token operator">=</span><span class="token number">5</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="전처리-파이프라인-—-pipeline-columntransformer" tabindex="-1"><a class="header-anchor" href="#전처리-파이프라인-—-pipeline-columntransformer"><span>전처리 파이프라인 — Pipeline + ColumnTransformer</span></a></h2><p>전처리를 모델과 한 객체로 묶으면 교차 검증·튜닝의 매 fold에서 fit이 train에만 적용돼 leakage가 원천 차단된다. 수치·범주 열에 서로 다른 전처리를 병렬로 건다.</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>pipeline <span class="token keyword">import</span> Pipeline</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>compose <span class="token keyword">import</span> ColumnTransformer</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>preprocessing <span class="token keyword">import</span> StandardScaler<span class="token punctuation">,</span> OneHotEncoder</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>impute <span class="token keyword">import</span> SimpleImputer</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>linear_model <span class="token keyword">import</span> LogisticRegression</span>
<span class="line"></span>
<span class="line">num_cols <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string">&quot;age&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;income&quot;</span><span class="token punctuation">]</span></span>
<span class="line">cat_cols <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string">&quot;city&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;grade&quot;</span><span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line">num_pipe <span class="token operator">=</span> Pipeline<span class="token punctuation">(</span><span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">(</span><span class="token string">&quot;impute&quot;</span><span class="token punctuation">,</span> SimpleImputer<span class="token punctuation">(</span>strategy<span class="token operator">=</span><span class="token string">&quot;median&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">(</span><span class="token string">&quot;scale&quot;</span><span class="token punctuation">,</span> StandardScaler<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line">cat_pipe <span class="token operator">=</span> Pipeline<span class="token punctuation">(</span><span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">(</span><span class="token string">&quot;impute&quot;</span><span class="token punctuation">,</span> SimpleImputer<span class="token punctuation">(</span>strategy<span class="token operator">=</span><span class="token string">&quot;most_frequent&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">(</span><span class="token string">&quot;onehot&quot;</span><span class="token punctuation">,</span> OneHotEncoder<span class="token punctuation">(</span>handle_unknown<span class="token operator">=</span><span class="token string">&quot;ignore&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">pre <span class="token operator">=</span> ColumnTransformer<span class="token punctuation">(</span><span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">(</span><span class="token string">&quot;num&quot;</span><span class="token punctuation">,</span> num_pipe<span class="token punctuation">,</span> num_cols<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">(</span><span class="token string">&quot;cat&quot;</span><span class="token punctuation">,</span> cat_pipe<span class="token punctuation">,</span> cat_cols<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">clf <span class="token operator">=</span> Pipeline<span class="token punctuation">(</span><span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">(</span><span class="token string">&quot;pre&quot;</span><span class="token punctuation">,</span> pre<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">(</span><span class="token string">&quot;model&quot;</span><span class="token punctuation">,</span> LogisticRegression<span class="token punctuation">(</span>max_iter<span class="token operator">=</span><span class="token number">1000</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line">clf<span class="token punctuation">.</span>fit<span class="token punctuation">(</span>X_train<span class="token punctuation">,</span> y_train<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="하이퍼파라미터-탐색-—-gridsearchcv-randomizedsearchcv" tabindex="-1"><a class="header-anchor" href="#하이퍼파라미터-탐색-—-gridsearchcv-randomizedsearchcv"><span>하이퍼파라미터 탐색 — GridSearchCV / RandomizedSearchCV</span></a></h2><p>Pipeline 스텝 이름에 <code>__</code>를 붙여 파라미터를 지정한다. 탐색 공간이 넓으면 Grid보다 Randomized가 효율적이다.</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>model_selection <span class="token keyword">import</span> GridSearchCV<span class="token punctuation">,</span> RandomizedSearchCV</span>
<span class="line"><span class="token keyword">from</span> scipy<span class="token punctuation">.</span>stats <span class="token keyword">import</span> loguniform</span>
<span class="line"></span>
<span class="line">param_grid <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token string">&quot;model__C&quot;</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token number">0.01</span><span class="token punctuation">,</span> <span class="token number">0.1</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">10</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line">gs <span class="token operator">=</span> GridSearchCV<span class="token punctuation">(</span>clf<span class="token punctuation">,</span> param_grid<span class="token punctuation">,</span> cv<span class="token operator">=</span><span class="token number">5</span><span class="token punctuation">,</span> scoring<span class="token operator">=</span><span class="token string">&quot;roc_auc&quot;</span><span class="token punctuation">,</span> n_jobs<span class="token operator">=</span><span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line">gs<span class="token punctuation">.</span>fit<span class="token punctuation">(</span>X_train<span class="token punctuation">,</span> y_train<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>gs<span class="token punctuation">.</span>best_params_<span class="token punctuation">,</span> gs<span class="token punctuation">.</span>best_score_<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">param_dist <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token string">&quot;model__C&quot;</span><span class="token punctuation">:</span> loguniform<span class="token punctuation">(</span><span class="token number">1e-3</span><span class="token punctuation">,</span> <span class="token number">1e2</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line">rs <span class="token operator">=</span> RandomizedSearchCV<span class="token punctuation">(</span></span>
<span class="line">    clf<span class="token punctuation">,</span> param_dist<span class="token punctuation">,</span> n_iter<span class="token operator">=</span><span class="token number">50</span><span class="token punctuation">,</span> cv<span class="token operator">=</span><span class="token number">5</span><span class="token punctuation">,</span></span>
<span class="line">    scoring<span class="token operator">=</span><span class="token string">&quot;roc_auc&quot;</span><span class="token punctuation">,</span> n_jobs<span class="token operator">=</span><span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">,</span> random_state<span class="token operator">=</span><span class="token number">42</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line">rs<span class="token punctuation">.</span>fit<span class="token punctuation">(</span>X_train<span class="token punctuation">,</span> y_train<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="주요-모델-인스턴스화" tabindex="-1"><a class="header-anchor" href="#주요-모델-인스턴스화"><span>주요 모델 인스턴스화</span></a></h2><p>베이스라인부터 앙상블까지 한 줄씩 모았다. 대부분 <code>random_state</code>를 고정해 재현성을 확보한다.</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>dummy <span class="token keyword">import</span> DummyClassifier</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>neighbors <span class="token keyword">import</span> KNeighborsClassifier</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>linear_model <span class="token keyword">import</span> LogisticRegression<span class="token punctuation">,</span> Ridge<span class="token punctuation">,</span> Lasso<span class="token punctuation">,</span> ElasticNet</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>svm <span class="token keyword">import</span> SVC</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>naive_bayes <span class="token keyword">import</span> GaussianNB</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>tree <span class="token keyword">import</span> DecisionTreeClassifier</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>ensemble <span class="token keyword">import</span> RandomForestClassifier<span class="token punctuation">,</span> GradientBoostingClassifier</span>
<span class="line"></span>
<span class="line">dummy <span class="token operator">=</span> DummyClassifier<span class="token punctuation">(</span>strategy<span class="token operator">=</span><span class="token string">&quot;most_frequent&quot;</span><span class="token punctuation">)</span>            <span class="token comment"># 베이스라인</span></span>
<span class="line">knn   <span class="token operator">=</span> KNeighborsClassifier<span class="token punctuation">(</span>n_neighbors<span class="token operator">=</span><span class="token number">15</span><span class="token punctuation">,</span> weights<span class="token operator">=</span><span class="token string">&quot;distance&quot;</span><span class="token punctuation">)</span></span>
<span class="line">logit <span class="token operator">=</span> LogisticRegression<span class="token punctuation">(</span>C<span class="token operator">=</span><span class="token number">1.0</span><span class="token punctuation">,</span> max_iter<span class="token operator">=</span><span class="token number">1000</span><span class="token punctuation">)</span></span>
<span class="line">ridge <span class="token operator">=</span> Ridge<span class="token punctuation">(</span>alpha<span class="token operator">=</span><span class="token number">1.0</span><span class="token punctuation">)</span>                                     <span class="token comment"># 회귀 L2</span></span>
<span class="line">lasso <span class="token operator">=</span> Lasso<span class="token punctuation">(</span>alpha<span class="token operator">=</span><span class="token number">0.01</span><span class="token punctuation">)</span>                                    <span class="token comment"># 회귀 L1</span></span>
<span class="line">enet  <span class="token operator">=</span> ElasticNet<span class="token punctuation">(</span>alpha<span class="token operator">=</span><span class="token number">0.01</span><span class="token punctuation">,</span> l1_ratio<span class="token operator">=</span><span class="token number">0.5</span><span class="token punctuation">)</span></span>
<span class="line">svc   <span class="token operator">=</span> SVC<span class="token punctuation">(</span>C<span class="token operator">=</span><span class="token number">1.0</span><span class="token punctuation">,</span> kernel<span class="token operator">=</span><span class="token string">&quot;rbf&quot;</span><span class="token punctuation">,</span> probability<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">)</span></span>
<span class="line">nb    <span class="token operator">=</span> GaussianNB<span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">tree  <span class="token operator">=</span> DecisionTreeClassifier<span class="token punctuation">(</span>max_depth<span class="token operator">=</span><span class="token number">6</span><span class="token punctuation">,</span> random_state<span class="token operator">=</span><span class="token number">42</span><span class="token punctuation">)</span></span>
<span class="line">rf    <span class="token operator">=</span> RandomForestClassifier<span class="token punctuation">(</span>n_estimators<span class="token operator">=</span><span class="token number">400</span><span class="token punctuation">,</span> n_jobs<span class="token operator">=</span><span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">,</span> random_state<span class="token operator">=</span><span class="token number">42</span><span class="token punctuation">)</span></span>
<span class="line">gb    <span class="token operator">=</span> GradientBoostingClassifier<span class="token punctuation">(</span>learning_rate<span class="token operator">=</span><span class="token number">0.05</span><span class="token punctuation">,</span> n_estimators<span class="token operator">=</span><span class="token number">300</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="평가-지표-함수" tabindex="-1"><a class="header-anchor" href="#평가-지표-함수"><span>평가 지표 함수</span></a></h2><p>혼동 행렬에서 파생되는 분류 지표와 회귀 지표를 함수로 바로 뽑는다. <code>classification_report</code>는 클래스별 정밀도·재현율·F1을 한눈에 보여준다.</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>metrics <span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    accuracy_score<span class="token punctuation">,</span> precision_score<span class="token punctuation">,</span> recall_score<span class="token punctuation">,</span> f1_score<span class="token punctuation">,</span></span>
<span class="line">    roc_auc_score<span class="token punctuation">,</span> average_precision_score<span class="token punctuation">,</span>      <span class="token comment"># ROC-AUC / PR-AUC</span></span>
<span class="line">    confusion_matrix<span class="token punctuation">,</span> classification_report<span class="token punctuation">,</span></span>
<span class="line">    mean_absolute_error<span class="token punctuation">,</span> mean_squared_error<span class="token punctuation">,</span> r2_score<span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">y_pred <span class="token operator">=</span> clf<span class="token punctuation">.</span>predict<span class="token punctuation">(</span>X_test<span class="token punctuation">)</span></span>
<span class="line">y_prob <span class="token operator">=</span> clf<span class="token punctuation">.</span>predict_proba<span class="token punctuation">(</span>X_test<span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token punctuation">:</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">]</span>         <span class="token comment"># 양성 클래스 확률</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>classification_report<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> y_pred<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;ROC-AUC:&quot;</span><span class="token punctuation">,</span> roc_auc_score<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> y_prob<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;PR-AUC :&quot;</span><span class="token punctuation">,</span> average_precision_score<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> y_prob<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 회귀</span></span>
<span class="line">rmse <span class="token operator">=</span> mean_squared_error<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> y_pred<span class="token punctuation">,</span> squared<span class="token operator">=</span><span class="token boolean">False</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;RMSE:&quot;</span><span class="token punctuation">,</span> rmse<span class="token punctuation">,</span> <span class="token string">&quot;R2:&quot;</span><span class="token punctuation">,</span> r2_score<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> y_pred<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="임계값-조정" tabindex="-1"><a class="header-anchor" href="#임계값-조정"><span>임계값 조정</span></a></h2><p>기본 임계값 0.5가 최적인 경우는 드물다. PR 곡선을 훑어 비용에 맞는 임계값을 고른다.</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token keyword">import</span> numpy <span class="token keyword">as</span> np</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>metrics <span class="token keyword">import</span> precision_recall_curve</span>
<span class="line"></span>
<span class="line">prec<span class="token punctuation">,</span> rec<span class="token punctuation">,</span> thr <span class="token operator">=</span> precision_recall_curve<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> y_prob<span class="token punctuation">)</span></span>
<span class="line">f1 <span class="token operator">=</span> <span class="token number">2</span> <span class="token operator">*</span> prec <span class="token operator">*</span> rec <span class="token operator">/</span> <span class="token punctuation">(</span>prec <span class="token operator">+</span> rec <span class="token operator">+</span> <span class="token number">1e-12</span><span class="token punctuation">)</span></span>
<span class="line">best_thr <span class="token operator">=</span> thr<span class="token punctuation">[</span>np<span class="token punctuation">.</span>argmax<span class="token punctuation">(</span>f1<span class="token punctuation">[</span><span class="token punctuation">:</span><span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">]</span>               <span class="token comment"># F1 최대 임계값</span></span>
<span class="line">y_pred_adj <span class="token operator">=</span> <span class="token punctuation">(</span>y_prob <span class="token operator">&gt;=</span> best_thr<span class="token punctuation">)</span><span class="token punctuation">.</span>astype<span class="token punctuation">(</span><span class="token builtin">int</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="확률-캘리브레이션-—-calibratedclassifiercv" tabindex="-1"><a class="header-anchor" href="#확률-캘리브레이션-—-calibratedclassifiercv"><span>확률 캘리브레이션 — CalibratedClassifierCV</span></a></h2><p>트리·SVM 등은 확률이 왜곡되기 쉽다. isotonic(비선형)이나 sigmoid(Platt)로 보정한다.</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>calibration <span class="token keyword">import</span> CalibratedClassifierCV</span>
<span class="line"></span>
<span class="line">calibrated <span class="token operator">=</span> CalibratedClassifierCV<span class="token punctuation">(</span></span>
<span class="line">    estimator<span class="token operator">=</span>rf<span class="token punctuation">,</span> method<span class="token operator">=</span><span class="token string">&quot;isotonic&quot;</span><span class="token punctuation">,</span> cv<span class="token operator">=</span><span class="token number">5</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line">calibrated<span class="token punctuation">.</span>fit<span class="token punctuation">(</span>X_train<span class="token punctuation">,</span> y_train<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="모델-해석-—-permutation-importance-shap" tabindex="-1"><a class="header-anchor" href="#모델-해석-—-permutation-importance-shap"><span>모델 해석 — permutation importance / SHAP</span></a></h2><p>분할 기반 중요도는 고카디널리티 피처에 편향되므로, 모델 불문인 permutation importance나 SHAP로 교차 검증한다.</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>inspection <span class="token keyword">import</span> permutation_importance</span>
<span class="line"></span>
<span class="line">r <span class="token operator">=</span> permutation_importance<span class="token punctuation">(</span></span>
<span class="line">    clf<span class="token punctuation">,</span> X_test<span class="token punctuation">,</span> y_test<span class="token punctuation">,</span> n_repeats<span class="token operator">=</span><span class="token number">10</span><span class="token punctuation">,</span></span>
<span class="line">    scoring<span class="token operator">=</span><span class="token string">&quot;roc_auc&quot;</span><span class="token punctuation">,</span> random_state<span class="token operator">=</span><span class="token number">42</span><span class="token punctuation">,</span> n_jobs<span class="token operator">=</span><span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">for</span> i <span class="token keyword">in</span> r<span class="token punctuation">.</span>importances_mean<span class="token punctuation">.</span>argsort<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token punctuation">:</span><span class="token punctuation">:</span><span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token keyword">print</span><span class="token punctuation">(</span>X_test<span class="token punctuation">.</span>columns<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>r<span class="token punctuation">.</span>importances_mean<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># SHAP (트리 모델)</span></span>
<span class="line"><span class="token keyword">import</span> shap</span>
<span class="line">explainer <span class="token operator">=</span> shap<span class="token punctuation">.</span>TreeExplainer<span class="token punctuation">(</span>rf<span class="token punctuation">)</span></span>
<span class="line">shap_values <span class="token operator">=</span> explainer<span class="token punctuation">.</span>shap_values<span class="token punctuation">(</span>X_test<span class="token punctuation">)</span></span>
<span class="line">shap<span class="token punctuation">.</span>summary_plot<span class="token punctuation">(</span>shap_values<span class="token punctuation">,</span> X_test<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="xgboost-—-early-stopping" tabindex="-1"><a class="header-anchor" href="#xgboost-—-early-stopping"><span>XGBoost — early stopping</span></a></h2><p>검증셋을 넘겨 early stopping으로 최적 트리 수를 자동으로 찾는다. sklearn 래퍼에서는 <code>early_stopping_rounds</code>를 생성자에 둔다(2.x 기준).</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token keyword">from</span> xgboost <span class="token keyword">import</span> XGBClassifier</span>
<span class="line"></span>
<span class="line">xgb <span class="token operator">=</span> XGBClassifier<span class="token punctuation">(</span></span>
<span class="line">    n_estimators<span class="token operator">=</span><span class="token number">2000</span><span class="token punctuation">,</span></span>
<span class="line">    learning_rate<span class="token operator">=</span><span class="token number">0.03</span><span class="token punctuation">,</span></span>
<span class="line">    max_depth<span class="token operator">=</span><span class="token number">6</span><span class="token punctuation">,</span></span>
<span class="line">    subsample<span class="token operator">=</span><span class="token number">0.8</span><span class="token punctuation">,</span></span>
<span class="line">    colsample_bytree<span class="token operator">=</span><span class="token number">0.8</span><span class="token punctuation">,</span></span>
<span class="line">    reg_lambda<span class="token operator">=</span><span class="token number">1.0</span><span class="token punctuation">,</span></span>
<span class="line">    eval_metric<span class="token operator">=</span><span class="token string">&quot;auc&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    early_stopping_rounds<span class="token operator">=</span><span class="token number">100</span><span class="token punctuation">,</span></span>
<span class="line">    n_jobs<span class="token operator">=</span><span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">    random_state<span class="token operator">=</span><span class="token number">42</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line">xgb<span class="token punctuation">.</span>fit<span class="token punctuation">(</span>X_train<span class="token punctuation">,</span> y_train<span class="token punctuation">,</span> eval_set<span class="token operator">=</span><span class="token punctuation">[</span><span class="token punctuation">(</span>X_valid<span class="token punctuation">,</span> y_valid<span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">,</span> verbose<span class="token operator">=</span><span class="token boolean">False</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;best_iteration:&quot;</span><span class="token punctuation">,</span> xgb<span class="token punctuation">.</span>best_iteration<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="lightgbm-—-early-stopping" tabindex="-1"><a class="header-anchor" href="#lightgbm-—-early-stopping"><span>LightGBM — early stopping</span></a></h2><p>콜백으로 early stopping과 로그 주기를 제어한다. leaf-wise 성장이라 <code>num_leaves</code>가 핵심 규제 노브다.</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token keyword">import</span> lightgbm <span class="token keyword">as</span> lgb</span>
<span class="line"><span class="token keyword">from</span> lightgbm <span class="token keyword">import</span> LGBMClassifier<span class="token punctuation">,</span> early_stopping<span class="token punctuation">,</span> log_evaluation</span>
<span class="line"></span>
<span class="line">lgbm <span class="token operator">=</span> LGBMClassifier<span class="token punctuation">(</span></span>
<span class="line">    n_estimators<span class="token operator">=</span><span class="token number">3000</span><span class="token punctuation">,</span></span>
<span class="line">    learning_rate<span class="token operator">=</span><span class="token number">0.03</span><span class="token punctuation">,</span></span>
<span class="line">    num_leaves<span class="token operator">=</span><span class="token number">63</span><span class="token punctuation">,</span></span>
<span class="line">    subsample<span class="token operator">=</span><span class="token number">0.8</span><span class="token punctuation">,</span></span>
<span class="line">    colsample_bytree<span class="token operator">=</span><span class="token number">0.8</span><span class="token punctuation">,</span></span>
<span class="line">    reg_lambda<span class="token operator">=</span><span class="token number">1.0</span><span class="token punctuation">,</span></span>
<span class="line">    n_jobs<span class="token operator">=</span><span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">,</span></span>
<span class="line">    random_state<span class="token operator">=</span><span class="token number">42</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line">lgbm<span class="token punctuation">.</span>fit<span class="token punctuation">(</span></span>
<span class="line">    X_train<span class="token punctuation">,</span> y_train<span class="token punctuation">,</span></span>
<span class="line">    eval_set<span class="token operator">=</span><span class="token punctuation">[</span><span class="token punctuation">(</span>X_valid<span class="token punctuation">,</span> y_valid<span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    eval_metric<span class="token operator">=</span><span class="token string">&quot;auc&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    callbacks<span class="token operator">=</span><span class="token punctuation">[</span>early_stopping<span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">)</span><span class="token punctuation">,</span> log_evaluation<span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="catboost-—-early-stopping" tabindex="-1"><a class="header-anchor" href="#catboost-—-early-stopping"><span>CatBoost — early stopping</span></a></h2><p>범주형 피처를 <code>cat_features</code>로 직접 넘기면 인코딩 없이 ordered target encoding을 내부에서 처리한다.</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token keyword">from</span> catboost <span class="token keyword">import</span> CatBoostClassifier</span>
<span class="line"></span>
<span class="line">cat <span class="token operator">=</span> CatBoostClassifier<span class="token punctuation">(</span></span>
<span class="line">    iterations<span class="token operator">=</span><span class="token number">3000</span><span class="token punctuation">,</span></span>
<span class="line">    learning_rate<span class="token operator">=</span><span class="token number">0.03</span><span class="token punctuation">,</span></span>
<span class="line">    depth<span class="token operator">=</span><span class="token number">6</span><span class="token punctuation">,</span></span>
<span class="line">    l2_leaf_reg<span class="token operator">=</span><span class="token number">3.0</span><span class="token punctuation">,</span></span>
<span class="line">    eval_metric<span class="token operator">=</span><span class="token string">&quot;AUC&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    random_seed<span class="token operator">=</span><span class="token number">42</span><span class="token punctuation">,</span></span>
<span class="line">    verbose<span class="token operator">=</span><span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line">cat<span class="token punctuation">.</span>fit<span class="token punctuation">(</span></span>
<span class="line">    X_train<span class="token punctuation">,</span> y_train<span class="token punctuation">,</span></span>
<span class="line">    cat_features<span class="token operator">=</span>cat_cols<span class="token punctuation">,</span>           <span class="token comment"># 범주형 열 이름/인덱스</span></span>
<span class="line">    eval_set<span class="token operator">=</span><span class="token punctuation">(</span>X_valid<span class="token punctuation">,</span> y_valid<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    early_stopping_rounds<span class="token operator">=</span><span class="token number">100</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="optuna-—-하이퍼파라미터-최적화-최소-예제" tabindex="-1"><a class="header-anchor" href="#optuna-—-하이퍼파라미터-최적화-최소-예제"><span>Optuna — 하이퍼파라미터 최적화 최소 예제</span></a></h2><p>베이지안 탐색으로 넓은 공간을 효율적으로 훑는다. objective가 교차 검증 점수를 돌려주게 하고 <code>study.optimize</code>로 반복한다.</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py" data-title="py"><pre><code><span class="line"><span class="token keyword">import</span> optuna</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>model_selection <span class="token keyword">import</span> cross_val_score</span>
<span class="line"></span>
<span class="line"><span class="token keyword">def</span> <span class="token function">objective</span><span class="token punctuation">(</span>trial<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">    params <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token string">&quot;n_estimators&quot;</span><span class="token punctuation">:</span> <span class="token number">3000</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;learning_rate&quot;</span><span class="token punctuation">:</span> trial<span class="token punctuation">.</span>suggest_float<span class="token punctuation">(</span><span class="token string">&quot;lr&quot;</span><span class="token punctuation">,</span> <span class="token number">1e-3</span><span class="token punctuation">,</span> <span class="token number">0.3</span><span class="token punctuation">,</span> log<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;num_leaves&quot;</span><span class="token punctuation">:</span> trial<span class="token punctuation">.</span>suggest_int<span class="token punctuation">(</span><span class="token string">&quot;num_leaves&quot;</span><span class="token punctuation">,</span> <span class="token number">15</span><span class="token punctuation">,</span> <span class="token number">255</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;subsample&quot;</span><span class="token punctuation">:</span> trial<span class="token punctuation">.</span>suggest_float<span class="token punctuation">(</span><span class="token string">&quot;subsample&quot;</span><span class="token punctuation">,</span> <span class="token number">0.5</span><span class="token punctuation">,</span> <span class="token number">1.0</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;colsample_bytree&quot;</span><span class="token punctuation">:</span> trial<span class="token punctuation">.</span>suggest_float<span class="token punctuation">(</span><span class="token string">&quot;colsample&quot;</span><span class="token punctuation">,</span> <span class="token number">0.5</span><span class="token punctuation">,</span> <span class="token number">1.0</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;reg_lambda&quot;</span><span class="token punctuation">:</span> trial<span class="token punctuation">.</span>suggest_float<span class="token punctuation">(</span><span class="token string">&quot;reg_lambda&quot;</span><span class="token punctuation">,</span> <span class="token number">1e-3</span><span class="token punctuation">,</span> <span class="token number">10.0</span><span class="token punctuation">,</span> log<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    model <span class="token operator">=</span> LGBMClassifier<span class="token punctuation">(</span><span class="token operator">**</span>params<span class="token punctuation">,</span> n_jobs<span class="token operator">=</span><span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">,</span> random_state<span class="token operator">=</span><span class="token number">42</span><span class="token punctuation">)</span></span>
<span class="line">    score <span class="token operator">=</span> cross_val_score<span class="token punctuation">(</span>model<span class="token punctuation">,</span> X<span class="token punctuation">,</span> y<span class="token punctuation">,</span> cv<span class="token operator">=</span><span class="token number">5</span><span class="token punctuation">,</span> scoring<span class="token operator">=</span><span class="token string">&quot;roc_auc&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span>mean<span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">return</span> score</span>
<span class="line"></span>
<span class="line">study <span class="token operator">=</span> optuna<span class="token punctuation">.</span>create_study<span class="token punctuation">(</span>direction<span class="token operator">=</span><span class="token string">&quot;maximize&quot;</span><span class="token punctuation">)</span></span>
<span class="line">study<span class="token punctuation">.</span>optimize<span class="token punctuation">(</span>objective<span class="token punctuation">,</span> n_trials<span class="token operator">=</span><span class="token number">50</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>study<span class="token punctuation">.</span>best_params<span class="token punctuation">,</span> study<span class="token punctuation">.</span>best_value<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>이어지는 <a href="/study/supervised-learning/appendix-references">참고 자료</a>에서는 여기 쓴 API의 공식 레퍼런스와 원 논문, 더 깊이 파고들 자료를 모았다.</p>`,45)]))}const i=s(t,[["render",o],["__file","appendix-cheatsheet.html.vue"]]),u=JSON.parse('{"path":"/study/supervised-learning/appendix-cheatsheet.html","title":"scikit-learn 치트시트","lang":"en-US","frontmatter":{"title":"scikit-learn 치트시트","description":"지도 학습 실무에서 자주 쓰는 scikit-learn 패턴을 코드 예제로 모은 레퍼런스. train_test_split·cross_val_score·StratifiedKFold/GroupKFold/TimeSeriesSplit, Pipeline+ColumnTransformer 골격, GridSearchCV/RandomizedSearchCV, 주요 모델 인스턴스화, 평가 지표, XGBoost/LightGBM/CatBoost early stopping, Optuna 최소 예제까지 다룬다.","date":"2026-07-03T00:00:00.000Z","tags":["scikit-learn","XGBoost","LightGBM","CatBoost","Cheatsheet"],"prev":"/study/supervised-learning/appendix-glossary","next":"/study/supervised-learning/appendix-references"},"headers":[{"level":1,"title":"scikit-learn 치트시트","slug":"scikit-learn-치트시트","link":"#scikit-learn-치트시트","children":[{"level":2,"title":"데이터 분할 — train_test_split","slug":"데이터-분할-—-train-test-split","link":"#데이터-분할-—-train-test-split","children":[]},{"level":2,"title":"교차 검증 — cross_val_score / cross_validate","slug":"교차-검증-—-cross-val-score-cross-validate","link":"#교차-검증-—-cross-val-score-cross-validate","children":[]},{"level":2,"title":"교차 검증 분할기 — Stratified / Group / TimeSeries","slug":"교차-검증-분할기-—-stratified-group-timeseries","link":"#교차-검증-분할기-—-stratified-group-timeseries","children":[]},{"level":2,"title":"전처리 파이프라인 — Pipeline + ColumnTransformer","slug":"전처리-파이프라인-—-pipeline-columntransformer","link":"#전처리-파이프라인-—-pipeline-columntransformer","children":[]},{"level":2,"title":"하이퍼파라미터 탐색 — GridSearchCV / RandomizedSearchCV","slug":"하이퍼파라미터-탐색-—-gridsearchcv-randomizedsearchcv","link":"#하이퍼파라미터-탐색-—-gridsearchcv-randomizedsearchcv","children":[]},{"level":2,"title":"주요 모델 인스턴스화","slug":"주요-모델-인스턴스화","link":"#주요-모델-인스턴스화","children":[]},{"level":2,"title":"평가 지표 함수","slug":"평가-지표-함수","link":"#평가-지표-함수","children":[]},{"level":2,"title":"임계값 조정","slug":"임계값-조정","link":"#임계값-조정","children":[]},{"level":2,"title":"확률 캘리브레이션 — CalibratedClassifierCV","slug":"확률-캘리브레이션-—-calibratedclassifiercv","link":"#확률-캘리브레이션-—-calibratedclassifiercv","children":[]},{"level":2,"title":"모델 해석 — permutation importance / SHAP","slug":"모델-해석-—-permutation-importance-shap","link":"#모델-해석-—-permutation-importance-shap","children":[]},{"level":2,"title":"XGBoost — early stopping","slug":"xgboost-—-early-stopping","link":"#xgboost-—-early-stopping","children":[]},{"level":2,"title":"LightGBM — early stopping","slug":"lightgbm-—-early-stopping","link":"#lightgbm-—-early-stopping","children":[]},{"level":2,"title":"CatBoost — early stopping","slug":"catboost-—-early-stopping","link":"#catboost-—-early-stopping","children":[]},{"level":2,"title":"Optuna — 하이퍼파라미터 최적화 최소 예제","slug":"optuna-—-하이퍼파라미터-최적화-최소-예제","link":"#optuna-—-하이퍼파라미터-최적화-최소-예제","children":[]}]}],"git":{},"filePathRelative":"_study/supervised-learning/appendix-cheatsheet.md"}');export{i as comp,u as data};
